package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeDivide(double[] v)
 */
public class OpenMapRealVector_ebeDivide_TriageGen3Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeDivideWithValidInput() {
        // Setup a sparse vector: [10.0, 0.0, 20.0]
        // Note: OpenMapRealVector is sparse, so we only set non-zero entries
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 10.0);
        vector.setEntry(2, 20.0);

        double[] divisor = {2.0, 5.0, 4.0};

        // Perform element-wise division
        OpenMapRealVector result = vector.ebeDivide(divisor);

        // Expected: [10/2, 0/5 (remains 0), 20/4] -> [5.0, 0.0, 5.0]
        Assert.assertEquals(3, result.getDimension());
        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(5.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeDivideWithEmptySparseVector() {
        // Setup an empty sparse vector
        OpenMapRealVector vector = new OpenMapRealVector(3);
        double[] divisor = {1.0, 1.0, 1.0};

        // Result should be an empty vector of same dimension
        OpenMapRealVector result = vector.ebeDivide(divisor);

        Assert.assertEquals(3, result.getDimension());
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeDivideWithDimensionMismatch() {
        // Vector dimension is 3
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 10.0);

        // Divisor dimension is 2
        double[] divisor = {2.0, 2.0};

        // Should throw DimensionMismatchException because v.length != vector.getDimension()
        vector.ebeDivide(divisor);
    }

    @Test
    public void testEbeDivideWithDivisionByZero() {
        // Setup vector
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 10.0);
        vector.setEntry(1, 5.0);

        // Divisor contains zero
        double[] divisor = {2.0, 0.0};

        // Result should contain Infinity
        OpenMapRealVector result = vector.ebeDivide(divisor);

        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        Assert.assertTrue(Double.isInfinite(result.getEntry(1)));
    }

    @Test
    public void testEbeDivideImmutability() {
        // Ensure the original vector is not modified
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 10.0);
        vector.setEntry(1, 20.0);

        double[] divisor = {2.0, 2.0};
        OpenMapRealVector result = vector.ebeDivide(divisor);

        // Check result
        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(10.0, result.getEntry(1), EPSILON);

        // Check original
        Assert.assertEquals(10.0, vector.getEntry(0), EPSILON);
        Assert.assertEquals(20.0, vector.getEntry(1), EPSILON);
    }
}
